$twig->getEnvironment()->addFilter(new \Twig\TwigFilter('initials', function (?string $name): string {
    if (!$name) return '?';
    $words = preg_split('/\s+/', trim($name));
    $initials = array_map(fn($w) => mb_strtoupper(mb_substr($w, 0, 1)), array_slice($words, 0, 2));
    return implode('', $initials);
}));

$twig->getEnvironment()->addFunction(new \Twig\TwigFunction('can', function (string $permission) use ($session): bool {
    $permissions = (array) $session->get('permissions');
    return in_array($permission, $permissions, true);
}));

